// LEFT JOIN en mémoire : garder les users sans commande.
export function leftJoin(users, orders) {
  const out = [];
  // BUG : comportement d'un INNER JOIN — les users sans commande disparaissent.
  for (const u of users) for (const o of orders) if (o.userId === u.id) out.push({ name: u.name, total: o.total });
  return out;
}

